sts((string) $out[$key], self::SIZE_UNITS) ? (string) $out[$key] : $fallback; } $out['name_prefix'] = mb_substr(trim((string) $out['name_prefix']), 0, 24); foreach (self::STRINGS as $key) { $out[$key] = trim((string) $out[$key]); } return $out; } public static function save(array $values): void { Settings::put(self::SETTING_KEY, [...self::blob(), ...$values]); } public static function setting(string $key): mixed { return self::all()[$key] ?? self::DEFAULTS[$key] ?? null; } public static function number(string $key): int { return (int) self::setting($key); } public static function flag(string $key): bool { return (bool) self::setting($key); } public static function enabled(): bool { return self::flag('enabled'); } public static function usable(): bool { return self::enabled() && self::eggs()->isNotEmpty() && self::locations()->isNotEmpty(); } public static function renewals(): bool { return self::flag('renew_enabled'); } public static function eggs(): \Illuminate\Support\Collection { $allowed = (array) self::setting('eggs'); if ($allowed === []) { return Egg::query()->whereRaw('1 = 0')->get(); } return Egg::query() ->with('nest') ->whereIn('uuid', $allowed) ->orderBy('name') ->get(); } public static function egg(string $uuid): ?Egg { if (!in_array($uuid, (array) self::setting('eggs'), true)) { return null; } return Egg::query()->with(['nest', 'variables'])->where('uuid', $uuid)->first(); } public static function locations(): \Illuminate\Support\Collection { $allowed = (array) self::setting('locations'); if ($allowed === []) { return Location::query()->whereRaw('1 = 0')->get(); } return Location::query() ->whereIn('id', $allowed) ->orderBy('short') ->get(); } public static function offers(int $location): bool { return in_array($location, (array) self::setting('locations'), true); } public static function nodeLimits(): array { return (array) self::setting('node_limits'); } public static function nodeLimit(int $node): int { return (int) (self::nodeLimits()[$node] ?? 0); } public static function locationNotes(): array { return (array) self::setting('location_notes'); } public static function locationNote(int $location): string { return (string) (self::locationNotes()[$location] ?? ''); } private static function notes(array $raw): array { $out = []; foreach ($raw as $location => $note) { $location = (int) $location; $note = mb_substr(trim((string) $note), 0, 120); if ($location > 0 && $note !== '') { $out[$location] = $note; } } ksort($out); return $out; } private static function limits(array $raw): array { $out = []; foreach ($raw as $node => $limit) { $node = (int) $node; $limit = max(0, min((int) $limit, self::CEILINGS['total'])); if ($node > 0 && $limit > 0) { $out[$node] = $limit; } } ksort($out); return $out; } public static function resources(): array { return [ 'cpu' => self::number('cpu'), 'memory' => self::number('memory'), 'swap' => self::number('swap'), 'disk' => self::number('disk'), 'io' => self::number('io'), 'databases' => self::number('databases'), 'allocations' => self::number('allocations'), 'backups' => self::number('backups'), ]; } public static function custom(): bool { return self::flag('custom_resources') && self::enabled(); } public static function cpuUnit(): string { return (string) self::setting('cpu_unit'); } public static function sizeUnit(string $key): string { return (string) self::setting($key . '_unit'); } public static function units(): array { return [ 'cpu' => self::cpuUnit(), 'memory' => self::sizeUnit('memory'), 'disk' => self::sizeUnit('disk'), ]; } public static function bounds(string $key, ?User $user = null, ?array $spent = null): array { if (!in_array($key, self::CHOOSABLE, true)) { $fixed = self::number($key); return ['min' => $fixed, 'max' => $fixed, 'default' => $fixed]; } $fixed = self::number($key); $total = $user === null ? self::pool($key) : self::poolFor($user, $key); $max = $total ?? ($fixed > 0 ? $fixed : self::CEILINGS[$key]); $floor = in_array($key, ['cpu', 'memory', 'disk'], true) ? 1 : 0; $min = max($floor, min(self::number('min_' . $key), $max)); $left = $user === null ? null : self::left($user, $key, $spent); $ceiling = $left === null ? $max : min($max, $left); return ['min' => $min, 'max' => $max, 'default' => max(0, min($fixed, $ceiling))]; } public static function pool(string $key): ?int { if (!in_array($key, self::CHOOSABLE, true)) { return null; } $pool = self::number('pool_' . $key); return $pool > 0 ? $pool : null; } public static function grant(User $user): array { $id = (int) $user->id; if (!array_key_exists($id, self::$grants)) { $row = ServerCreateGrant::query()->where('user_id', $id)->first(); $out = []; foreach (self::GRANTED as $key) { $out[$key] = max(0, (int) ($row?->{$key} ?? 0)); } self::$grants[$id] = $out; } return self::$grants[$id]; } public static function poolFor(User $user, string $key): ?int { $own = self::grant($user)[$key] ?? 0; return $own > 0 ? $own : self::pool($key); } public static function allowedServers(User $user): int { $own = self::grant($user)['servers'] ?? 0; return $own > 0 ? $own : self::number('per_user'); } public static function saveGrant(User $user, array $values): void { $row = []; foreach (self::GRANTED as $key) { $ceiling = self::CEILINGS[$key === 'servers' ? 'per_user' : 'pool_' . $key] ?? PHP_INT_MAX; $row[$key] = max(0, min((int) ($values[$key] ?? 0), $ceiling)); } if (array_sum($row) === 0) { ServerCreateGrant::query()->where('user_id', $user->id)->delete(); } else { ServerCreateGrant::query()->updateOrCreate(['user_id' => $user->id], $row); } unset(self::$grants[(int) $user->id]); } public static function allowanceFor(User $user): array { $grant = self::grant($user); $spent = self::spent($user); $allowed = self::allowedServers($user); $custom = self::custom(); $out = [ 'servers' => [ 'used' => self::held($user), 'total' => $allowed === 0 ? null : $allowed, 'left' => self::remaining($user), 'own' => $grant['servers'], 'min' => null, ], ]; foreach (self::CHOOSABLE as $key) { $out[$key] = [ 'used' => (int) ($spent[$key] ?? 0), 'total' => self::poolFor($user, $key), 'left' => self::left($user, $key, $spent), 'own' => $grant[$key], 'min' => $custom ? (int) self::bounds($key, $user, $spent)['min'] : self::number($key), ]; } return $out; } public static function spent(User $user, ?int $except = null): array { $row = Server::query() ->join('dezerx_free_servers', 'dezerx_free_servers.server_id', '=', 'servers.id') ->where('dezerx_free_servers.user_id', $user->id) ->when($except !== null, fn ($query) => $query->where('servers.id', '!=', $except)) ->selectRaw('COALESCE(SUM(servers.cpu), 0) AS cpu') ->selectRaw('COALESCE(SUM(servers.memory), 0) AS memory') ->selectRaw('COALESCE(SUM(servers.disk), 0) AS disk') ->selectRaw('COALESCE(SUM(servers.database_limit), 0) AS database_total') ->selectRaw('COALESCE(SUM(servers.allocation_limit), 0) AS allocation_total') ->selectRaw('COALESCE(SUM(servers.backup_limit), 0) AS backup_total') ->first(); return [ 'cpu' => (int) ($row->cpu ?? 0), 'memory' => (int) ($row->memory ?? 0), 'disk' => (int) ($row->disk ?? 0), 'databases' => (int) ($row->database_total ?? 0), 'allocations' => (int) ($row->allocation_total ?? 0), 'backups' => (int) ($row->backup_total ?? 0), ]; } public static function left(User $user, string $key, ?array $spent = null): ?int { $pool = self::poolFor($user, $key); if ($pool === null) { return null; } $spent ??= self::spent($user); return max(0, $pool - (int) ($spent[$key] ?? 0)); } public static function chosen(User $user, array $wanted, ?int $except = null): array { $resources = self::resources(); if (!self::custom()) { return $resources; } $spent = self::spent($user, $except); foreach (self::CHOOSABLE as $key) { $bounds = self::bounds($key, $user, $spent); $value = array_key_exists($key, $wanted) && is_numeric($wanted[$key]) ? (int) $wanted[$key] : $bounds['default']; $value = max($bounds['min'], min($value, $bounds['max'])); $left = self::left($user, $key, $spent); if ($left !== null && $value > $left) { throw new DisplayException( 'That is more than you have left to give out. Lower it and try again.', ); } $resources[$key] = $value; } return $resources; } public static function held(User $user): int { return FreeServer::query()->where('user_id', $user->id)->count(); } public static function issued(): int { return FreeServer::query()->count(); } public static function remaining(User $user): ?int { $perUser = self::allowedServers($user); $total = self::number('total'); $left = $perUser === 0 ? null : max(0, $perUser - self::held($user)); if ($total > 0) { $globally = max(0, $total - self::issued()); $left = $left === null ? $globally : min($left, $globally); } return $left; } public static function refusal(User $user): ?string { if (!self::usable()) { return 'unavailable'; } if ($user->demo) { return 'demo'; } if (self::flag('require_totp') && !$user->use_totp) { return 'totp'; } if (Discord::required() && !Discord::linked($user)) { return 'discord'; } $hours = self::number('min_account_age_hours'); if ($hours > 0 && $user->created_at?->addHours($hours)->isFuture()) { return 'young'; } $remaining = self::remaining($user); if ($remaining !== null && $remaining < 1) { return self::number('total') > 0 && self::issued() >= self::number('total') ? 'full' : 'limit'; } if (self::custom()) { $spent = self::spent($user); foreach (self::CHOOSABLE as $key) { $left = self::left($user, $key, $spent); if ($left !== null && $left < self::bounds($key, $user, $spent)['min']) { return 'pool'; } } } return null; } public static function nextDeadline(?\DateTimeInterface $from = null): ?CarbonImmutable { if (!self::renewals()) { return null; } $every = max(1, self::number('renew_every')); $start = $from === null ? CarbonImmutable::now() : CarbonImmutable::instance($from); return match (self::setting('renew_unit')) { self::UNIT_HOURS => $start->addHours($every), self::UNIT_WEEKS => $start->addWeeks($every), self::UNIT_MONTHS => $start->addMonths($every), default => $start->addDays($every), }; } public static function period(): string { $every = max(1, self::number('renew_every')); $unit = mb_strtolower(self::UNITS[self::setting('renew_unit')] ?? 'days'); return $every . ' ' . ($every === 1 ? rtrim($unit, 's') : $unit); } public static function withinWindow(?\DateTimeInterface $deadline): bool { if ($deadline === null) { return false; } $window = self::number('renew_window_hours'); return $window === 0 || CarbonImmutable::now()->addHours($window)->greaterThanOrEqualTo(CarbonImmutable::instance($deadline)); } public static function timezone(): string { return (string) (config('app.timezone') ?: 'UTC'); } public static function payload(): array { return [ 'enabled' => self::usable(), 'renewals' => self::enabled() && self::renewals(), ]; } private static function clamp(string $key, int $value): int { $floor = $key === 'swap' ? -1 : ($key === 'io' ? 10 : 0); $ceiling = self::CEILINGS[$key] ?? PHP_INT_MAX; return max($floor, min($value, $ceiling)); } } 